<?php require_once __DIR__.'/../config.php'; $u=require_login(); if($u['role']!=='driver') redirect('dashboard.php'); if($_SERVER['REQUEST_METHOD']!=='POST') redirect('dashboard.php'); csrf_check(); $stmt=db()->prepare("UPDATE schedules SET confirmed=1, confirmed_at=datetime('now') WHERE id=? AND driver_id=?"); $stmt->execute([(int)$_POST['id'],$u['id']]); flash('Escala confirmada com sucesso.'); redirect('dashboard.php');
